package com.dynasty.blueprint.artifact;

import com.dynasty.blueprint.boss.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.animal.Cow;
import net.minecraft.world.entity.monster.Zombie;
import net.minecraft.world.item.*;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraftforge.gametest.*;
import java.util.*;

/** Seven native acceptance sources. Never run during the user's Java pause. */
@GameTestHolder("dynasty_army") @PrefixGameTestTemplate(false)
public final class ArtifactGameTests {
    private static final TicketType<UUID> TYPE=TicketType.create("dynasty_artifact_qa",UUID::compareTo);
    private record Ticket(ChunkPos chunk,UUID id){}
    private static final Map<ServerLevel,List<Ticket>> TICKETS=new HashMap<>();
    private static final Map<ServerLevel,List<Entity>> OWNED=new HashMap<>();
    private static final Map<ServerLevel,Set<Long>> YARDS=new HashMap<>();
    static <T extends Entity>T own(GameTestHelper h,T e){OWNED.computeIfAbsent(h.getLevel(),k->new ArrayList<>()).add(e);return e;}
    @AfterBatch(batch="longyin_artifact") public static void release(ServerLevel w){var entities=OWNED.remove(w);var s=MarshalCourtyardState.get(w);if(entities!=null)for(var e:entities){if(e instanceof ServerPlayer p){for(var fx:w.getEntitiesOfClass(ArtifactWave.class,p.getBoundingBox().inflate(32),f->f.ownedBy(p)))fx.discard();s.firstRewarded.remove(p.getUUID());s.bladeClaimed.remove(p.getUUID());ArtifactAbility.forget(p.getUUID());}if(!e.isRemoved())e.discard();}var yards=YARDS.remove(w);if(yards!=null)for(var key:yards){var y=s.yards.remove(key);if(y!=null&&y.memorial!=null){var blade=w.getEntity(y.memorial);if(blade!=null)blade.discard();}}s.setDirty();var tickets=TICKETS.remove(w);if(tickets!=null)for(var t:tickets)w.getChunkSource().removeRegionTicket(TYPE,t.chunk(),2,t.id(),true);}
    static ServerPlayer player(GameTestHelper h){var at=h.absolutePos(new BlockPos(30,2,30));for(int x=(at.getX()-20)>>4;x<=(at.getX()+20)>>4;x++)for(int z=(at.getZ()-20)>>4;z<=(at.getZ()+20)>>4;z++){var t=new Ticket(new ChunkPos(x,z),UUID.randomUUID());h.getLevel().getChunkSource().addRegionTicket(TYPE,t.chunk(),2,t.id(),true);TICKETS.computeIfAbsent(h.getLevel(),k->new ArrayList<>()).add(t);h.getLevel().getChunk(x,z);}for(int x=-18;x<=18;x++)for(int z=-18;z<=18;z++)h.getLevel().setBlock(at.offset(x,-1,z),Blocks.SANDSTONE.defaultBlockState(),3);
        var p=own(h,new ServerPlayer(h.getLevel().getServer(),h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"artifact-qa")));p.connection=new net.minecraft.server.network.ServerGamePacketListenerImpl(h.getLevel().getServer(),new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),p);p.setGameMode(GameType.SURVIVAL);p.moveTo(at.getX()+.5,at.getY(),at.getZ()+.5,0,0);p.setNoGravity(true);p.setOnGround(true);p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);p.setHealth(1000);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(ArtifactContent.LONGYIN.get()));h.getLevel().addNewPlayer(p);h.onEachTick(p::doTick);return p;}
    private static Cow cow(GameTestHelper h,ServerPlayer p,double z){var c=own(h,EntityType.COW.create(h.getLevel()));c.moveTo(p.getX(),p.getY(),p.getZ()+z,0,0);c.setNoAi(true);c.setNoGravity(true);c.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);c.getAttribute(Attributes.KNOCKBACK_RESISTANCE).setBaseValue(1);c.setHealth(1000);h.getLevel().addFreshEntity(c);return c;}
    private static void begin(GameTestHelper h,ServerPlayer p){h.assertTrue(ArtifactAbility.begin(p,p.getMainHandItem()),"Server records exact current stack and its own start clock");p.startUsingItem(InteractionHand.MAIN_HAND);}
    @GameTest(template="cauldron_pit_test",timeoutTicks=10,batch="longyin_artifact")
    public static void emptyIntentRejectsForeignPayloadAndValidatesActualMainHand(GameTestHelper h){var b=new net.minecraft.network.FriendlyByteBuf(io.netty.buffer.Unpooled.buffer());try{ArtifactSwingRequest.decode(b);b.writeLong(123);boolean rejected=false;try{ArtifactSwingRequest.decode(b);}catch(io.netty.handler.codec.DecoderException expected){rejected=true;}h.assertTrue(rejected,"Client cannot append coordinates, damage or an identity");}finally{b.release();}var p=player(h);p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);h.assertTrue(!ArtifactCombat.swing(p),"Request without real current artifact denied");h.assertTrue(com.dynasty.network.DynastyNetwork.protocolSchema().contains("18=com.dynasty.blueprint.artifact.ArtifactSwingRequest:PLAY_TO_SERVER:v1"),"Fixed append-only direction/revision in full handshake schema");h.succeed();}
    @GameTest(template="cauldron_pit_test",timeoutTicks=105,batch="longyin_artifact")
    public static void chargeUsesFortyRealTicksAndStackSwapCancelsOwnership(GameTestHelper h){var p=player(h);var stack=p.getMainHandItem();h.runAfterDelay(4,()->begin(h,p));h.runAfterDelay(43,()->{h.assertTrue(!ArtifactAbility.finish(p,stack),"39real server ticks cannot launch the wave");p.stopUsingItem();});h.runAfterDelay(45,()->begin(h,p));h.runAfterDelay(46,()->{p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_SWORD));h.assertTrue(!ArtifactAbility.finish(p,stack),"A different held stack cannot spend the original charge");p.stopUsingItem();p.setItemInHand(InteractionHand.MAIN_HAND,stack);});h.runAfterDelay(48,()->begin(h,p));h.runAfterDelay(88,()->{p.setOnGround(true);h.assertTrue(ArtifactAbility.finish(p,stack)&&stack.getDamageValue()==2&&p.getCooldowns().isOnCooldown(stack.getItem()),"40real ticks spend durability once and establish native plus persistent cooldown");p.stopUsingItem();h.assertTrue(!ArtifactAbility.finish(p,stack),"Duplicate release has no retained session");h.succeed();});}
    @GameTest(template="cauldron_pit_test",timeoutTicks=90,batch="longyin_artifact")
    public static void realTenCellWaveHitsOnceAndCannotBorrowSwitchedWeaponDamage(GameTestHelper h){var p=player(h);var target=cow(h,p,8);var beyond=cow(h,p,13);h.runAfterDelay(4,()->begin(h,p));h.runAfterDelay(44,()->{p.setOnGround(true);h.assertTrue(ArtifactAbility.finish(p,p.getMainHandItem()),"Native floor wave created");p.stopUsingItem();p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.WOODEN_SWORD));});h.runAfterDelay(70,()->{h.assertTrue(Math.abs(target.getHealth()-(1000-13*1.5F))<.01&&beyond.getHealth()==1000,"Snapshot13damage, single accepted hit, ten finite ground cells");h.assertTrue(h.getLevel().getEntitiesOfClass(ArtifactWave.class,p.getBoundingBox().inflate(32),f->f.ownedBy(p)).isEmpty(),"Twenty-tick wave removed");h.succeed();});}
    @GameTest(template="cauldron_pit_test",timeoutTicks=90,batch="longyin_artifact")
    public static void lateRaisedWallStopsGroundWaveBeforeRemoteVictim(GameTestHelper h){var p=player(h);var target=cow(h,p,8);h.runAfterDelay(4,()->begin(h,p));h.runAfterDelay(44,()->{p.setOnGround(true);h.assertTrue(ArtifactAbility.finish(p,p.getMainHandItem()),"Wave begins on real floor");p.stopUsingItem();var block=BlockPos.containing(p.position()).offset(0,0,4);for(int x=-1;x<=1;x++)for(int y=0;y<3;y++)h.getLevel().setBlock(block.offset(x,y,0),Blocks.STONE.defaultBlockState(),3);});h.runAfterDelay(70,()->{h.assertTrue(target.getHealth()==1000&&h.getLevel().getEntitiesOfClass(ArtifactWave.class,p.getBoundingBox().inflate(32),f->f.ownedBy(p)).isEmpty(),"New wall clips before damage; no terrain erasure or terrain bypass");h.succeed();});}
    @GameTest(template="cauldron_pit_test",timeoutTicks=65,batch="longyin_artifact")
    public static void lastDurabilityChargedReleaseStillCleansItsOriginalAbility(GameTestHelper h){var p=player(h);var stack=p.getMainHandItem();stack.setDamageValue(stack.getMaxDamage()-1);h.runAfterDelay(4,()->begin(h,p));h.runAfterDelay(44,()->{p.setOnGround(true);h.assertTrue(ArtifactAbility.finish(p,stack)&&stack.isEmpty()&&!ArtifactAbility.USES.containsKey(p.getUUID()),"Breaking the actual stack during release cannot cast its now-empty Item back to ArtifactItem; original ability session cleans once");p.stopUsingItem();h.assertTrue(h.getLevel().getEntitiesOfClass(ArtifactWave.class,p.getBoundingBox().inflate(3),f->f.ownedBy(p)).size()==1,"One legitimate final-durability wave still exists");h.succeed();});}
    @GameTest(template="cauldron_pit_test",timeoutTicks=275,batch="longyin_artifact")
    public static void confirmedVictoryMemorialAllowsOneClaimAndPersistsUniqueUuid(GameTestHelper h){var p=player(h);p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);var state=MarshalCourtyardState.get(h.getLevel());var centre=p.blockPosition().offset(3,0,0);var yard=state.register(centre);YARDS.computeIfAbsent(h.getLevel(),k->new HashSet<>()).add(centre.asLong());var boss=own(h,BlindMarshalContent.MARSHAL.get().create(h.getLevel()));boss.moveTo(centre.getX()+.5,centre.getY(),centre.getZ()+.5,0,0);boss.bindArena(centre);boss.setNoAi(true);yard.boss=boss.getUUID();h.getLevel().addFreshEntity(boss);boss.hurt(boss.damageSources().genericKill(),10000);h.assertTrue(yard.defeated&&state.firstRewarded.contains(p.getUUID())&&!MarshalCourtyards.placeMemorial(h.getLevel(),yard),"Confirmed matching death only; twelve-second death cannot be skipped");h.runAfterDelay(250,()->{h.assertTrue(MarshalCourtyards.placeMemorial(h.getLevel(),yard)||yard.memorial!=null,"Actual persistent blade appears after death completes");var blade=own(h,(MarshalBladeMemorial)h.getLevel().getEntity(yard.memorial));p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);h.assertTrue(blade.interact(p,InteractionHand.MAIN_HAND)==InteractionResult.SUCCESS,"Eligible first killer claims by actual empty-hand interaction");h.assertTrue(blade.interact(p,InteractionHand.MAIN_HAND)==InteractionResult.PASS&&!blade.isRemoved()&&!MarshalCourtyards.placeMemorial(h.getLevel(),yard),"Duplicate claim denied and same memorial remains");var saved=MarshalCourtyardState.load(state.save(new CompoundTag()));h.assertTrue(saved.bladeClaimed.contains(p.getUUID())&&yard.memorial.equals(saved.yards.get(centre.asLong()).memorial),"Claim and memorial UUID survive native SavedData serialization");h.succeed();});}
    @GameTest(template="cauldron_pit_test",timeoutTicks=135,batch="longyin_artifact")
    public static void nativeFrontClashThenSurroundReductionWithRearException(GameTestHelper h){var p=player(h);var foes=new ArrayList<Zombie>();for(int i=0;i<3;i++){var z=own(h,EntityType.ZOMBIE.create(h.getLevel()));double a=(i-1)*Math.PI/3;z.moveTo(p.getX()+Math.sin(a)*3.8,p.getY(),p.getZ()+Math.cos(a)*3.8,0,0);z.setNoAi(true);z.setNoGravity(true);h.getLevel().addFreshEntity(z);foes.add(z);}h.runAfterDelay(80,()->h.assertTrue(ArtifactCombat.swing(p),"Real full-strength native swing opens server clash window"));h.runAfterDelay(82,()->{float health=p.getHealth();p.hurt(p.damageSources().mobAttack(foes.get(0)),10);h.assertTrue(p.getHealth()==health&&ArtifactCombat.counterReady(p,p.getMainHandItem())&&foes.get(0).getPersistentData().getLong("DynastyArtifactParriedUntil")>h.getLevel().getGameTime(),"Actual incoming front strike in2ticks is canceled once and grants one instant release");});h.runAfterDelay(90,()->{float health=p.getHealth();p.hurt(p.damageSources().mobAttack(foes.get(1)),10);h.assertTrue(Math.abs(health-p.getHealth()-7.5F)<.01,"Three real hostile bodies give exactly25percent front physical mitigation after clash window");p.addEffect(new net.minecraft.world.effect.MobEffectInstance(com.dynasty.expansion.ExpansionEffects.STAGGER.get(),40));h.assertTrue(!p.hasEffect(com.dynasty.expansion.ExpansionEffects.STAGGER.get()),"Surrounded stance rejects registered interruption effect");});h.runAfterDelay(113,()->{var rear=foes.get(2);rear.setPos(p.getX(),p.getY(),p.getZ()-3.8);float health=p.getHealth();p.hurt(p.damageSources().mobAttack(rear),10);h.assertTrue(Math.abs(health-p.getHealth()-10)<.01,"Same surrounding count gives no rear mitigation and cannot replay spent clash");h.succeed();});}
}
